App.my.KEY = 'milk';
App.my.set = () => Object.assign({ litres: 1, rate: 60 }, App.load('milk-set', {}));
App.my.paid = () => App.load('milk-paid', {});
App.my.list = () => App.items(App.my.KEY).slice().sort((a, b) => (b.date || '').localeCompare(a.date || '') || b.at - a.at);
App.my.month = (key) => App.items(App.my.KEY).filter((d) => App.monthKey(d.date) === key);
App.my.byDate = (date) => App.items(App.my.KEY).find((d) => d.date === date);
App.my.litres = (l) => l.reduce((s, d) => s + (d.missed ? 0 : Number(d.litres) || 0), 0);
App.my.bill = (l) => l.reduce((s, d) => s + (d.missed ? 0 : (Number(d.litres) || 0) * (Number(d.rate) || 0)), 0);
App.my.put = (date, rec) => {
  const old = App.my.byDate(date);
  if (old) App.update(App.my.KEY, old.id, rec); else App.add(App.my.KEY, Object.assign({ date }, rec));
};
App.my.widget = async () => {
  const k = App.monthKey(new Date()), l = App.my.month(k), paid = App.my.paid()[k];
  try { await App.widget('🥛 పాలు', ['ఈ నెల: ' + App.n(App.my.litres(l), 1) + ' L · ' + App.rs(App.my.bill(l)), paid ? '✅ చెల్లించారు' : 'ఇంకా చెల్లించలేదు']); } catch (e) { /* the widget only helps */ }
};
App.onStart(() => { App.my.widget(); });
App.onJarvis('add', (d) => {
  const s = App.my.set(), date = /^\d{4}-\d{2}-\d{2}$/.test(String(d.date || '')) ? d.date : App.today();
  if (d.missed === true) { App.my.put(date, { litres: 0, rate: s.rate, missed: true }); App.my.widget(); return App.date(date, 'short') + ' పాలు రాలేదు అని రాశాను'; }
  const litres = Number(d.litres) > 0 ? Number(d.litres) : s.litres;
  App.my.put(date, { litres, rate: s.rate, missed: false });
  App.my.widget();
  return App.date(date, 'short') + ' ' + App.n(litres, 1) + ' లీటర్లు రాశాను';
});

App.onShow('home', () => {
  const k = App.monthKey(new Date()), l = App.my.month(k), s = App.my.set(), t = App.my.byDate(App.today());
  App.text('#home-l', App.n(App.my.litres(l), 1) + ' L');
  App.text('#home-rs', App.rs(App.my.bill(l)));
  App.text('#home-got', '✅ వచ్చాయి (' + App.n(s.litres, 1) + ' L)');
  App.text('#home-today', !t ? 'ఇంకా రాయలేదు' : t.missed ? '✗ రాలేదు అని రాశారు' : '✅ ' + App.n(t.litres, 1) + ' L · ' + App.rs((Number(t.litres) || 0) * (Number(t.rate) || 0)));
  const days = l.sort((a, b) => (b.date || '').localeCompare(a.date || ''));
  App.set('#home-list', days.length ? '<div class="list">' + days.map((d) => `
    <div class="item${d.missed ? ' miss' : ''}" data-id="${App.esc(d.id)}">
      <div class="ic">${d.missed ? '✗' : '🥛'}</div>
      <div class="w"><div class="t">${d.missed ? 'రాలేదు' : App.esc(App.n(d.litres, 1)) + ' లీటర్లు'}</div><div class="s">${App.date(d.date, 'day')}${d.note ? ' · ' + App.esc(d.note) : ''}</div></div>
      <div class="r">${d.missed ? '' : App.rs((Number(d.litres) || 0) * (Number(d.rate) || 0))}</div>
    </div>`).join('') + '</div>'
    : '<div class="empty"><div class="e">🥛</div>ఈ నెల ఇంకా ఏమీ రాయలేదు. పైన "వచ్చాయి" నొక్కండి.</div>');
});
App.click('#home-got', () => { const s = App.my.set(); App.my.put(App.today(), { litres: s.litres, rate: s.rate, missed: false }); App.my.widget(); App.beep('ok'); App.toast('ఈరోజు ' + App.n(s.litres, 1) + ' L రాశాను'); App.refresh(); });
App.click('#home-more', async () => {
  const s = App.my.set(), v = await App.input('ఈరోజు ఎన్ని లీటర్లు?', { type: 'number', value: s.litres });
  if (v == null) return;
  const litres = Number(v);
  if (!(litres > 0)) { App.toast('లీటర్లు సరిగా రాయండి'); return; }
  App.my.put(App.today(), { litres, rate: s.rate, missed: false }); App.my.widget(); App.beep('ok'); App.refresh();
});
App.click('#home-miss', () => { App.my.put(App.today(), { litres: 0, rate: App.my.set().rate, missed: true }); App.my.widget(); App.toast('ఈరోజు రాలేదు అని రాశాను'); App.refresh(); });
App.click('#home-add', () => App.go('day'));
App.click('#home-list .item', (ev, el) => App.go('day', App.find(App.my.KEY, el.dataset.id)));

App.onShow('day', (d) => {
  const s = App.my.set();
  App.my.editing = d && d.id ? d.id : null;
  App.title(App.my.editing ? 'రోజు మార్చండి' : 'ఒక రోజు రాయండి');
  App.val('#day-date', d && d.date ? d.date : App.today());
  App.val('#day-l', d ? d.litres : s.litres);
  App.val('#day-rate', d ? d.rate : s.rate);
  App.val('#day-miss', !!(d && d.missed));
  App.val('#day-note', d && d.note ? d.note : '');
  App.show('#day-del', !!App.my.editing);
});
App.click('#day-save', () => {
  const missed = App.val('#day-miss') === true, litres = Number(App.val('#day-l')), rate = Number(App.val('#day-rate'));
  if (!missed && !(litres > 0)) { App.toast('లీటర్లు రాయండి (రాకపోతే "రాలేదు" టిక్ చేయండి)'); return; }
  if (!(rate >= 0)) { App.toast('ధర సరిగా రాయండి'); return; }
  const rec = { date: App.val('#day-date') || App.today(), litres: missed ? 0 : litres, rate, missed, note: App.val('#day-note') };
  if (App.my.editing) App.update(App.my.KEY, App.my.editing, rec); else App.my.put(rec.date, rec);
  App.my.widget(); App.beep('ok'); App.toast('దాచాను'); App.back();
});
App.click('#day-del', async () => {
  if (!App.my.editing) return;
  if (await App.ask('ఈ రోజు తీసేయాలా?', 'తీసేయి', 'వద్దు')) { App.del(App.my.KEY, App.my.editing); App.my.widget(); App.toast('తీసేశాను'); App.back(); }
});

App.my.keys = (n) => { const ks = []; for (let i = n - 1; i >= 0; i--) { const d = new Date(); d.setDate(1); d.setMonth(d.getMonth() - i); ks.push(App.monthKey(d)); } return ks; };
App.onShow('months', () => {
  const ks = App.my.keys(6), paid = App.my.paid(), s = App.my.set();
  App.chart('#months-chart', { type: 'bar', labels: ks.map((k) => App.month(k + '-01').split(' ')[0]), values: ks.map((k) => App.my.bill(App.my.month(k))), money: true });
  const rows = App.my.keys(12).reverse().filter((k) => App.my.month(k).length);
  App.set('#months-list', rows.length ? '<div class="list">' + rows.map((k) => {
    const l = App.my.month(k), miss = l.filter((d) => d.missed).length;
    return `<div class="item" data-k="${App.esc(k)}"><div class="ic">📅</div>
      <div class="w"><div class="t">${App.esc(App.month(k + '-01'))}</div><div class="s">${App.n(App.my.litres(l), 1)} L${miss ? ' · ' + miss + ' రోజులు రాలేదు' : ''}</div></div>
      <div class="r">${App.rs(App.my.bill(l))}<div class="${paid[k] ? 'paid' : 'muted'}">${paid[k] ? '✅ చెల్లించారు' : 'చెల్లించాను →'}</div></div></div>`;
  }).join('') + '</div>' : '<div class="empty"><div class="e">📅</div>ఇంకా నెలలు లేవు.</div>');
  App.text('#months-set-s', 'రోజూ ' + App.n(s.litres, 1) + ' L · ₹' + App.n(s.rate, 2) + ' / లీటర్');
});
App.click('#months-list .item', async (ev, el) => {
  const k = el.dataset.k, paid = App.my.paid();
  if (paid[k]) { if (await App.ask(App.month(k + '-01') + ': "చెల్లించారు" తీసేయాలా?', 'తీసేయి', 'వద్దు')) { delete paid[k]; App.save('milk-paid', paid); } }
  else if (await App.ask(App.month(k + '-01') + ' బిల్లు ' + App.rs(App.my.bill(App.my.month(k))) + ' చెల్లించారా?', 'చెల్లించాను', 'ఇంకా లేదు')) { paid[k] = { at: Date.now() }; App.save('milk-paid', paid); App.beep('done'); }
  App.my.widget(); App.refresh();
});
App.click('#months-set', async () => {
  const s = App.my.set();
  const v = await App.form('⚙️ రోజూ ఎంత, ధర', [{ key: 'litres', label: 'రోజూ లీటర్లు', type: 'number', value: s.litres }, { key: 'rate', label: 'ధర (₹ / లీటర్)', type: 'number', value: s.rate }]);
  if (!v) return;
  const litres = Number(v.litres), rate = Number(v.rate);
  if (!(litres > 0) || !(rate >= 0)) { App.toast('సరిగా రాయండి'); return; }
  App.save('milk-set', { litres, rate }); App.toast('మార్చాను: కొత్త రోజుల నుంచి'); App.refresh();
});
App.my.thisMonth = () => App.my.month(App.monthKey(new Date())).sort((a, b) => (a.date || '').localeCompare(b.date || ''));
App.click('#months-share', async () => {
  const l = App.my.thisMonth(), miss = l.filter((d) => d.missed).length;
  const t = '🥛 ' + App.month(App.today()) + ' పాల బిల్లు: ' + App.n(App.my.litres(l), 1) + ' లీటర్లు, ' + App.rs(App.my.bill(l)) + (miss ? '\n' + miss + ' రోజులు పాలు రాలేదు' : '');
  try { await App.share(t); } catch (e) { App.toast('షేర్ కాలేదు'); }
});
App.click('#months-pdf', async () => {
  const l = App.my.thisMonth();
  const rows = l.map((d) => `<tr><td>${App.date(d.date, 'short')}</td><td class="n">${d.missed ? 'రాలేదు' : App.n(d.litres, 1)}</td><td class="n">${d.missed ? '' : App.rs(d.rate)}</td><td class="n">${d.missed ? '' : App.rs((Number(d.litres) || 0) * (Number(d.rate) || 0))}</td></tr>`).join('');
  const html = `<h2>${App.esc(App.month(App.today()))} పాల బిల్లు</h2><p>${App.n(App.my.litres(l), 1)} లీటర్లు · <b>${App.rs(App.my.bill(l))}</b></p>`
    + `<table><tr><th>తేదీ</th><th>లీటర్లు</th><th>ధర</th><th>మొత్తం</th></tr>${rows}</table>`;
  try { await App.pdf('పాల బిల్లు ' + App.monthKey(new Date()), html); } catch (e) { App.toast('PDF కాలేదు'); }
});
